    [FunctionalTheory][InlineData(false)][InlineData(true)]
    public async Task GivenOwnedTypedItemsAndTwoProfiles_WhenReplacing_ThenAdvanceOneProfileAndPreserveContentAndOtherLinks(bool sameGuid)
    {
        using var additionalScoped1=new ProtectionFixture();
        using var owner=new ProtectionFixture();using var scoped=new ProtectionFixture();var state=await ProfileSetup.Create(fixture,owner);var one=await Add(state,owner,scoped);var two=await Add(state,owner,additionalScoped1);var items=await AssociationSetup.Items(fixture,state,sameGuid?Guid.NewGuid():null);var input=For(items);var original=await Row(one.ProfileId);var resourceBytes=await Resources(items);var r=await Store().SetAsync(new(state.Actor,state.Verifier,one.ProfileId,input),default);Assert.Null(r.Error);Assert.Equal(2,r.Data!.Revision);Assert.True(r.Data.ServerSequence>original.ServerSequence);Assert.Equal(input.RecordIds,r.Data.RecordIds);Assert.Equal(input.FolderIds,r.Data.FolderIds);Assert.Equal(input.CollectionIds,r.Data.CollectionIds);Assert.Null((await Store().SetAsync(new(state.Actor,state.Verifier,two.ProfileId,input),default)).Error);
        var current=await Row(one.ProfileId);Assert.Equal(original.Envelope,current.Envelope);Assert.Equal(original.KeyWrappers,current.KeyWrappers);Assert.Equal(original.EditedAt,current.EditedAt);Assert.Equal(resourceBytes,await Resources(items));var cleared=await Store().SetAsync(new(state.Actor,state.Verifier,one.ProfileId,Input(2)),default);Assert.Null(cleared.Error);Assert.Equal(3,cleared.Data!.Revision);Assert.True(cleared.Data.ServerSequence>r.Data.ServerSequence);Assert.Empty(cleared.Data.RecordIds);await using var db=fixture.CreateContext();Assert.False(await db.ProfileRecords.AnyAsync(x=>x.ProfileId==original.Id));Assert.False(await db.ProfileFolders.AnyAsync(x=>x.ProfileId==original.Id));Assert.False(await db.ProfileCollections.AnyAsync(x=>x.ProfileId==original.Id));Assert.Single(await db.ProfileRecords.Where(x=>x.RecordId==items.Record.Id).ToArrayAsync());Assert.Equal(resourceBytes,await Resources(items));
    }
