    [FunctionalTheory][InlineData("recordForeign")][InlineData("folderForeign")][InlineData("recordTrash")][InlineData("folderTrash")][InlineData("recordErased")][InlineData("folderErased")][InlineData("recordMissing")][InlineData("folderMissing")][InlineData("collectionMissing")]
    public async Task GivenHiddenAssociationTarget_WhenReplacing_Then404WithoutPartialLinks(string kind)
    {
        using var owner=new ProtectionFixture();using var scoped=new ProtectionFixture();var state=await ProfileSetup.Create(fixture,owner);var foreign=await ProfileSetup.Create(fixture,owner);var profile=await Add(state,owner,scoped);var items=await AssociationSetup.Items(fixture,state);var foreignItems=kind.Contains("Foreign")?await AssociationSetup.Items(fixture,foreign):null;await using(var db=fixture.CreateContext()){if(kind=="recordTrash")await db.Records.Where(x=>x.Id==items.Record.Id).ExecuteUpdateAsync(x=>x.SetProperty(v=>v.DeletedAt,DateTimeOffset.UtcNow));if(kind=="folderTrash")await db.Folders.Where(x=>x.Id==items.Folder.Id).ExecuteUpdateAsync(x=>x.SetProperty(v=>v.DeletedAt,DateTimeOffset.UtcNow));if(kind.Contains("Erased")){db.TerminalErasures.Add(new(){ResourceId=kind.StartsWith("record")?items.Record.PublicId:items.Folder.PublicId,ResourceKind=kind.StartsWith("record")?"record":"folder",DeletedAt=DateTimeOffset.UtcNow});await db.SaveChangesAsync();}}
        var input=For(items);if(kind=="recordForeign")input=input with {RecordIds=[foreignItems!.Record.PublicId]};if(kind=="folderForeign")input=input with {FolderIds=[foreignItems!.Folder.PublicId]};if(kind=="recordMissing")input=input with {RecordIds=[Guid.NewGuid()]};if(kind=="folderMissing")input=input with {FolderIds=[Guid.NewGuid()]};if(kind=="collectionMissing")input=input with {CollectionIds=[Guid.NewGuid()]};var before=await Snapshot(profile.ProfileId);Assert.Equal("not_found",(await Store().SetAsync(new(state.Actor,state.Verifier,profile.ProfileId,input),default)).Error);Assert.Equal(before,await Snapshot(profile.ProfileId));await NoLinks(profile.ProfileId);
