    [FunctionalTheory][InlineData("revoked","not_found")][InlineData("missing","not_found")][InlineData("recipient","not_found")][InlineData("access","not_found")][InlineData("state","not_found")][InlineData("zeroRevision","not_found")][InlineData("trash","not_found")][InlineData("erased","not_found")][InlineData("closing","not_found")][InlineData("ownerErased","not_found")][InlineData("signature","persistence_unavailable")][InlineData("identity","persistence_unavailable")][InlineData("epoch","persistence_unavailable")][InlineData("grantId","persistence_unavailable")][InlineData("grantRevision","persistence_unavailable")][InlineData("author","persistence_unavailable")][InlineData("blob","persistence_unavailable")][InlineData("ownerPins","persistence_unavailable")][InlineData("recipientPins","persistence_unavailable")][InlineData("collectionEpoch","persistence_unavailable")][InlineData("collectionEnvelope","persistence_unavailable")]
    public async Task GivenUnavailableOrCorruptSharedGrant_WhenReplacing_ThenFailClosedAndPreserveState(string kind,string error)
    {
        using var owner=new ProtectionFixture();using var client=new ProtectionFixture();using var scoped=new ProtectionFixture();var foreign=await ProfileSetup.Create(fixture,owner);var state=await ProfileSetup.Create(fixture,client);var profile=await Add(state,client,scoped);var items=await AssociationSetup.Items(fixture,foreign);var grant=await AssociationSetup.Grant(fixture,foreign,owner,state,client,items.Collection);await using(var db=fixture.CreateContext()){var g=await db.CollectionGrants.SingleAsync(x=>x.Id==grant.Id);if(kind=="revoked")g.State=CollectionGrantState.Revoked;if(kind=="missing")db.CollectionGrants.Remove(g);if(kind=="recipient")g.RecipientAccountId=foreign.InternalId;if(kind=="access")g.Access=(CollectionGrantAccess)99;if(kind=="state")g.State=(CollectionGrantState)99;if(kind=="zeroRevision")g.Revision=0;if(kind=="collectionEpoch")await db.Collections.Where(x=>x.Id==items.Collection.Id).ExecuteUpdateAsync(x=>x.SetProperty(v=>v.KeyEpoch,2));if(kind=="collectionEnvelope")await db.Collections.Where(x=>x.Id==items.Collection.Id).ExecuteUpdateAsync(x=>x.SetProperty(v=>v.Envelope,new byte[]{1}));if(kind=="trash")await db.Collections.Where(x=>x.Id==items.Collection.Id).ExecuteUpdateAsync(x=>x.SetProperty(v=>v.DeletedAt,DateTimeOffset.UtcNow));if(kind=="erased"||kind=="ownerErased")db.TerminalErasures.Add(new(){ResourceId=kind=="erased"?items.Collection.PublicId:foreign.AccountId,ResourceKind=kind=="erased"?"collection":"account",DeletedAt=DateTimeOffset.UtcNow});if(kind=="closing")await db.Accounts.Where(x=>x.Id==foreign.InternalId).ExecuteUpdateAsync(x=>x.SetProperty(v=>v.State,AccountState.ClosurePending));if(kind is "ownerPins" or "recipientPins")await db.VaultProtections.Where(x=>x.AccountId==(kind=="ownerPins"?foreign.InternalId:state.InternalId)).ExecuteUpdateAsync(x=>x.SetProperty(v=>v.Material,new byte[]{1}));
            if(kind is "signature" or "identity" or "epoch" or "grantId" or "grantRevision" or "author"){var w=JsonSerializer.Deserialize<RecipientEnvelope>(g.RecipientKeyEnvelope,ProtectionFixture.Json)!;w=kind switch {"signature"=>w with {Signature=ProtectionFixture.Encode(new byte[64])},"identity"=>w with {RecipientIdentityId=Guid.NewGuid()},"epoch"=>w with {KeyEpoch=2},"grantId"=>w with {GrantId=Guid.NewGuid()},"grantRevision"=>w with {GrantRevision=2},_=>w with {AuthorKeyFingerprint=client.Material.AuthorKey.Fingerprint()}};g.RecipientKeyEnvelope=JsonSerializer.SerializeToUtf8Bytes(w,ProtectionFixture.Json);}if(kind=="blob")g.RecipientKeyEnvelope=[1];await db.SaveChangesAsync();}
        var before=await Snapshot(profile.ProfileId);Assert.Equal(error,(await Store().SetAsync(new(state.Actor,state.Verifier,profile.ProfileId,new(1,[],[],[items.Collection.PublicId])),default)).Error);Assert.Equal(before,await Snapshot(profile.ProfileId));await NoLinks(profile.ProfileId);
    }
