    {
        using var owner=new ProtectionFixture();using var scoped=new ProtectionFixture();var state=await ProfileSetup.Create(fixture,owner);var profile=await Add(state,owner,scoped);var items=await AssociationSetup.Items(fixture,state);var request=new ProfileAssociationRequest(state.Actor,state.Verifier,profile.ProfileId,For(items));var set=Store().SetAsync(request,default);Task other;string? otherError;if(kind=="edit"){var op=new ProfileUpdateStore(fixture).UpdateAsync(new(state.Actor,state.Verifier,profile.ProfileId,new(1,ProfileSetup.Envelope(),profile.EditedAt)),default);other=op;await Task.WhenAll(set,other);otherError=op.Result.Error;}else if(kind=="trash"){var op=new ProfileTrashStore(fixture).TrashAsync(new(state.Actor,state.Verifier,profile.ProfileId,1),default);other=op;await Task.WhenAll(set,other);otherError=op.Result.Error;}else{var op=Store().SetAsync(request,default);other=op;await Task.WhenAll(set,other);otherError=op.Result.Error;}Assert.True((set.Result.Error is null)^(otherError is null));if(set.Result.Error is not null)Assert.Equal(kind=="trash"?"not_found":"revision_conflict",set.Result.Error);else Assert.Equal("revision_conflict",otherError);var before=await Snapshot(profile.ProfileId);Assert.Equal((await Row(profile.ProfileId)).DeletedAt is null?"revision_conflict":"not_found",(await Store().SetAsync(request,default)).Error);Assert.Equal(before,await Snapshot(profile.ProfileId));Assert.Equal(2,(await Row(profile.ProfileId)).Revision);
    }
    [FunctionalTheory][InlineData("account",1)][InlineData("session",1)][InlineData("profile",1)][InlineData("profile",22)][InlineData("collection",1)][InlineData("grant",1)]
    public async Task GivenNaturalExpiryDuringAnyLockWait_WhenSettingAssociations_ThenDenyBeforeRevisionOrWrites(string kind,long revision)
    {
        using var owner=new ProtectionFixture();using var client=new ProtectionFixture();using var scoped=new ProtectionFixture();var foreign=await ProfileSetup.Create(fixture,owner);var state=await ProfileSetup.Create(fixture,client);var profile=await Add(state,client,scoped);var items=await AssociationSetup.Items(fixture,foreign);var grant=await AssociationSetup.Grant(fixture,foreign,owner,state,client,items.Collection);var deadline=DateTimeOffset.UtcNow.AddSeconds(2);await using(var db=fixture.CreateContext())await db.VaultAccessSessions.Where(x=>x.HandleVerifier==state.Verifier).ExecuteUpdateAsync(x=>x.SetProperty(v=>v.ExpiresAt,deadline));await using var holder=fixture.CreateContext();await using var tx=await holder.Database.BeginTransactionAsync();if(kind=="account")await holder.Database.ExecuteSqlInterpolatedAsync($"SELECT 1 FROM cerberus.account WHERE id={state.InternalId} FOR UPDATE");else if(kind=="session")await holder.Database.ExecuteSqlInterpolatedAsync($"SELECT 1 FROM cerberus.vault_access_session WHERE handle_verifier={state.Verifier} FOR UPDATE");else if(kind=="profile")await holder.Database.ExecuteSqlInterpolatedAsync($"SELECT 1 FROM cerberus.profile WHERE public_id={profile.ProfileId} FOR UPDATE");else if(kind=="collection")await holder.Database.ExecuteSqlInterpolatedAsync($"SELECT 1 FROM cerberus.collection WHERE id={items.Collection.Id} FOR UPDATE");else await holder.Database.ExecuteSqlInterpolatedAsync($"SELECT 1 FROM cerberus.collection_grant WHERE id={grant.Id} FOR UPDATE");var reached=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var before=await Snapshot(profile.ProfileId);var pending=new ProfileAssociationStore(new ProfileSetup.Factory(fixture,new LockSignal(reached,kind))).SetAsync(new(state.Actor,state.Verifier,profile.ProfileId,new(revision,[],[],[items.Collection.PublicId])),default);await reached.Task.WaitAsync(TimeSpan.FromSeconds(10));Assert.False(pending.IsCompleted);var remaining=deadline-DateTimeOffset.UtcNow;if(remaining>TimeSpan.Zero)await Task.Delay(remaining+TimeSpan.FromMilliseconds(100));await tx.CommitAsync();Assert.Equal("vault_access_denied",(await pending).Error);Assert.Equal(before,await Snapshot(profile.ProfileId));await NoLinks(profile.ProfileId);
    }
    [FunctionalFact]
    public async Task GivenGrantRevokedWhileWaitingForItsLock_WhenSettingAssociations_ThenObserveRevocationAndPersistNothing()
    {
        using var owner=new ProtectionFixture();using var client=new ProtectionFixture();using var scoped=new ProtectionFixture();var foreign=await ProfileSetup.Create(fixture,owner);var state=await ProfileSetup.Create(fixture,client);var profile=await Add(state,client,scoped);var items=await AssociationSetup.Items(fixture,foreign);var grant=await AssociationSetup.Grant(fixture,foreign,owner,state,client,items.Collection);await using var holder=fixture.CreateContext();await using var tx=await holder.Database.BeginTransactionAsync();await holder.Database.ExecuteSqlInterpolatedAsync($"SELECT 1 FROM cerberus.collection_grant WHERE id={grant.Id} FOR UPDATE");var reached=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var before=await Snapshot(profile.ProfileId);var pending=new ProfileAssociationStore(new ProfileSetup.Factory(fixture,new LockSignal(reached,"grant"))).SetAsync(new(state.Actor,state.Verifier,profile.ProfileId,new(1,[],[],[items.Collection.PublicId])),default);await reached.Task.WaitAsync(TimeSpan.FromSeconds(10));Assert.False(pending.IsCompleted);await holder.CollectionGrants.Where(x=>x.Id==grant.Id).ExecuteUpdateAsync(x=>x.SetProperty(g=>g.State,CollectionGrantState.Revoked));await tx.CommitAsync();Assert.Equal("not_found",(await pending).Error);Assert.Equal(before,await Snapshot(profile.ProfileId));await NoLinks(profile.ProfileId);
    }
    [FunctionalTheory][InlineData("ownerClosing")][InlineData("recordTrash")]
    public async Task GivenPermissionChangesImmediatelyBeforeWrite_WhenSettingAssociations_ThenFinalStatementRejects(string kind)
    {
        using var owner=new ProtectionFixture();using var client=new ProtectionFixture();using var scoped=new ProtectionFixture();var foreign=await ProfileSetup.Create(fixture,owner);var state=await ProfileSetup.Create(fixture,client);var profile=await Add(state,client,scoped);var own=await AssociationSetup.Items(fixture,state);var shared=await AssociationSetup.Items(fixture,foreign);await AssociationSetup.Grant(fixture,foreign,owner,state,client,shared.Collection);var before=await Snapshot(profile.ProfileId);var r=await new ProfileAssociationStore(new ProfileSetup.Factory(fixture,new ChangeBeforeWrite(fixture,kind,foreign.InternalId,own.Record.Id))).SetAsync(new(state.Actor,state.Verifier,profile.ProfileId,new(1,[own.Record.PublicId],[],[shared.Collection.PublicId])),default);Assert.Equal("not_found",r.Error);Assert.Equal(before,await Snapshot(profile.ProfileId));await NoLinks(profile.ProfileId);
