    [FunctionalTheory][InlineData("write")][InlineData("delete")][InlineData("insert")]
    public async Task GivenFailureDuringReplacement_WhenSettingAssociations_ThenRollbackOldLinksAndMetadataAndRetrySucceeds(string stage)
    {
        using var owner=new ProtectionFixture();using var scoped=new ProtectionFixture();var state=await ProfileSetup.Create(fixture,owner);var profile=await Add(state,owner,scoped);var old=await AssociationSetup.Items(fixture,state);var next=await AssociationSetup.Items(fixture,state);Assert.Null((await Store().SetAsync(new(state.Actor,state.Verifier,profile.ProfileId,For(old)),default)).Error);var before=await Snapshot(profile.ProfileId);var request=new ProfileAssociationRequest(state.Actor,state.Verifier,profile.ProfileId,For(next,2));Assert.Equal("persistence_unavailable",(await new ProfileAssociationStore(new ProfileSetup.Factory(fixture,new Fail(stage))).SetAsync(request,default)).Error);Assert.Equal(before,await Snapshot(profile.ProfileId));await using(var db=fixture.CreateContext()){var pid=(await Row(profile.ProfileId)).Id;Assert.Equal(old.Record.Id,(await db.ProfileRecords.SingleAsync(x=>x.ProfileId==pid)).RecordId);Assert.Equal(old.Folder.Id,(await db.ProfileFolders.SingleAsync(x=>x.ProfileId==pid)).FolderId);Assert.Equal(old.Collection.Id,(await db.ProfileCollections.SingleAsync(x=>x.ProfileId==pid)).CollectionId);}Assert.Null((await Store().SetAsync(request,default)).Error);
    }
    [FunctionalTheory][InlineData("zeroRevision","persistence_unavailable")][InlineData("zeroSequence","persistence_unavailable")][InlineData("unsafeSequence","persistence_unavailable")][InlineData("maxRevision","revision_conflict")][InlineData("unsafeRevision","persistence_unavailable")]
    public async Task GivenCorruptOrExhaustedProfileMetadata_WhenSettingAssociations_ThenNoMutation(string kind,string error)
    {
        using var owner=new ProtectionFixture();using var scoped=new ProtectionFixture();var state=await ProfileSetup.Create(fixture,owner);var profile=await Add(state,owner,scoped);await using(var db=fixture.CreateContext()){var row=await db.Profiles.SingleAsync(x=>x.PublicId==profile.ProfileId);if(kind=="zeroRevision")row.Revision=0;if(kind=="zeroSequence")row.ServerSequence=0;if(kind=="unsafeSequence")row.ServerSequence=9007199254740992;if(kind=="maxRevision")row.Revision=9007199254740991;if(kind=="unsafeRevision")row.Revision=9007199254740992;await db.SaveChangesAsync();}var before=await Snapshot(profile.ProfileId);Assert.Equal(error,(await Store().SetAsync(new(state.Actor,state.Verifier,profile.ProfileId,Input(kind=="maxRevision"?9007199254740991:1)),default)).Error);Assert.Equal(before,await Snapshot(profile.ProfileId));await NoLinks(profile.ProfileId);
    }
    [FunctionalTheory][InlineData("actor","authentication_required")][InlineData("id","validation_failed")][InlineData("input","validation_failed")][InlineData("revision","validation_failed")][InlineData("array","validation_failed")]
    public async Task GivenInvalidInternalInput_WhenSettingAssociations_ThenRejectBeforeMutation(string kind,string error)
    {using var owner=new ProtectionFixture();using var scoped=new ProtectionFixture();var state=await ProfileSetup.Create(fixture,owner);var profile=await Add(state,owner,scoped);var input=Input();if(kind=="input")input=null!;if(kind=="revision")input=input with {ExpectedRevision=0};if(kind=="array")input=input with {RecordIds=null!};var before=await Snapshot(profile.ProfileId);Assert.Equal(error,(await Store().SetAsync(new(kind=="actor"?Guid.Empty:state.Actor,state.Verifier,kind=="id"?Guid.Empty:profile.ProfileId,input),default)).Error);Assert.Equal(before,await Snapshot(profile.ProfileId));await NoLinks(profile.ProfileId);}
