    private static ProfileAssociationInput For(AssociationSetup.ResourceSet items,long revision=1)=>new(revision,[items.Record.PublicId],[items.Folder.PublicId],[items.Collection.PublicId]);
    private async Task<string> Resources(AssociationSetup.ResourceSet items){await using var db=fixture.CreateContext();return JsonSerializer.Serialize(new{R=await db.Records.AsNoTracking().SingleAsync(x=>x.Id==items.Record.Id),F=await db.Folders.AsNoTracking().SingleAsync(x=>x.Id==items.Folder.Id),C=await db.Collections.AsNoTracking().SingleAsync(x=>x.Id==items.Collection.Id)});}
    private async Task NoLinks(Guid id){var p=await Row(id);await using var db=fixture.CreateContext();Assert.False(await db.ProfileRecords.AnyAsync(x=>x.ProfileId==p.Id));Assert.False(await db.ProfileFolders.AnyAsync(x=>x.ProfileId==p.Id));Assert.False(await db.ProfileCollections.AnyAsync(x=>x.ProfileId==p.Id));}
    private sealed class LockSignal(TaskCompletionSource reached,string kind):DbCommandInterceptor
    {private void Check(DbCommand c){var table=kind switch {"account"=>"cerberus.account","session"=>"cerberus.vault_access_session","profile"=>"cerberus.profile","collection"=>"cerberus.collection ",_=>"cerberus.collection_grant"};if((c.CommandText.Contains("FOR UPDATE")||c.CommandText.Contains("FOR SHARE"))&&c.CommandText.Contains(table))reached.TrySetResult();}public override ValueTask<InterceptionResult<int>> NonQueryExecutingAsync(DbCommand c,CommandEventData d,InterceptionResult<int> r,CancellationToken ct=default){Check(c);return ValueTask.FromResult(r);}public override ValueTask<InterceptionResult<DbDataReader>> ReaderExecutingAsync(DbCommand c,CommandEventData d,InterceptionResult<DbDataReader> r,CancellationToken ct=default){Check(c);return ValueTask.FromResult(r);}}
    private sealed class ChangeBeforeWrite(PostgresFixture fixture,string kind,long owner,long record):DbCommandInterceptor
    {public override async ValueTask<InterceptionResult<int>> NonQueryExecutingAsync(DbCommand c,CommandEventData d,InterceptionResult<int> r,CancellationToken ct=default){if(c.CommandText.Contains("UPDATE cerberus.profile")){await using var db=fixture.CreateContext();if(kind=="ownerClosing")await db.Accounts.Where(x=>x.Id==owner).ExecuteUpdateAsync(x=>x.SetProperty(a=>a.State,AccountState.ClosurePending),ct);else await db.Records.Where(x=>x.Id==record).ExecuteUpdateAsync(x=>x.SetProperty(a=>a.DeletedAt,DateTimeOffset.UtcNow),ct);}return r;}}
    private sealed class Fail(string stage):DbCommandInterceptor
    {private bool written;public override ValueTask<int> NonQueryExecutedAsync(DbCommand c,CommandExecutedEventData d,int r,CancellationToken ct=default){if(c.CommandText.Contains("UPDATE cerberus.profile"))written=true;return ValueTask.FromResult(r);}public override ValueTask<InterceptionResult<int>> NonQueryExecutingAsync(DbCommand c,CommandEventData d,InterceptionResult<int> r,CancellationToken ct=default){if(stage=="delete"&&c.CommandText.Contains("DELETE FROM cerberus.profile_record"))throw new TimeoutException("synthetic link delete failure");return ValueTask.FromResult(r);}public override ValueTask<InterceptionResult<DbDataReader>> ReaderExecutingAsync(DbCommand c,CommandEventData d,InterceptionResult<DbDataReader> r,CancellationToken ct=default){if(stage=="write"&&written || stage=="insert"&&c.CommandText.Contains("INSERT INTO cerberus.profile_record"))throw new TimeoutException("synthetic replacement failure");return ValueTask.FromResult(r);}}
    private ProfileAssociationStore Store()=>new(fixture);
    private static ProfileAssociationInput Input(long revision=1)=>new(revision,[],[],[]);
    private async Task<ProfileCreateInput> Add(ProfileSetup.State s,ProtectionFixture owner,ProtectionFixture scoped,string mode="Master"){var i=ProfileSetup.Input(s,owner,scoped,mode);Assert.Null((await new ProfileCreateStore(fixture).CreateAsync(new(s.Actor,s.Verifier,i),default)).Error);return i;}
    private async Task<Profile> Row(Guid id){await using var db=fixture.CreateContext();return await db.Profiles.AsNoTracking().SingleAsync(x=>x.PublicId==id);}
    private async Task<string> Snapshot(Guid id)=>JsonSerializer.Serialize(await Row(id));
    private sealed class Signal(TaskCompletionSource reached,string kind):DbCommandInterceptor
    {public override ValueTask<InterceptionResult<int>> NonQueryExecutingAsync(DbCommand c,CommandEventData d,InterceptionResult<int> r,CancellationToken ct=default){if(c.CommandText.Contains("FOR UPDATE")&&c.CommandText.Contains(kind switch {"account"=>"cerberus.account","session"=>"cerberus.vault_access_session",_=>"cerberus.profile"}))reached.TrySetResult();return ValueTask.FromResult(r);}}
    private sealed class Expire(DateTimeOffset deadline):DbCommandInterceptor
    {public override async ValueTask<InterceptionResult<int>> NonQueryExecutingAsync(DbCommand c,CommandEventData d,InterceptionResult<int> r,CancellationToken ct=default){if(c.CommandText.Contains("UPDATE cerberus.profile")){var wait=deadline-DateTimeOffset.UtcNow;if(wait>TimeSpan.Zero)await Task.Delay(wait+TimeSpan.FromMilliseconds(100),ct);}return r;}}
